        const d3 = c.def;
        const g2 = gainNode(o, d3.vol ?? 1);
        let tail = g2;
        if (d3.drive) tail = tail.connect(shaper(o, d3.drive));
        if (d3.pan) {
          const p = ownNode(o, o.ctx.createStereoPanner());
          p.pan.value = d3.pan;
          tail = tail.connect(p);
        }
